const r = await tools.pwsh({
  description: "Read newest pnpm operation logs",
  command: `
Get-ChildItem 'C:\\Users\\jjq21\\.dsh\\profiles\\desktop\\.plugin-manager\\logs' -Directory | Sort-Object LastWriteTime -Descending | Select-Object -First 3 | ForEach-Object {
  Write-Output ('===== ' + $_.Name + ' ' + $_.LastWriteTime + ' =====')
  Get-ChildItem $_.FullName -File | ForEach-Object { Write-Output ('--- ' + $_.Name + ' ---'); Get-Content -Raw $_.FullName }
}
`,
  timeoutMs: 60000,
});
if (r.kind === "foreground") console.log(r.stdout.text.slice(0, 6000));
